190	/// Interactive multi-select overlay. All candidates start checked. Returns
191	/// the selected subset, or `None` if the user cancelled.
192	pub(super) fn tui_discover(
193	    stdout: &mut impl Write,
194	    candidates: Vec<CandidateRepo>,
195	    w: usize,
196	    h: usize,
197	) -> Option<Vec<CandidateRepo>> {
198	    use crossterm::{cursor, event::{self, Event, KeyCode}, queue, terminal::{self, ClearType}};
199	
200	    let mut selected: Vec<bool> = vec![true; candidates.len()];
201	    let mut sel = 0usize;
202	    let content_h = h.saturating_sub(2); // reserve title row + status bar
203	
204	    let t = crate::theme::get();
205	
206	    loop {
207	        let mut buf: Vec<u8> = Vec::with_capacity((w + 40) * (h + 2));
208	
209	        // Title row
210	        queue!(buf, cursor::MoveTo(0, 0), terminal::Clear(ClearType::UntilNewLine)).ok();
211	        let n_sel: usize = selected.iter().filter(|&&s| s).count();
212	        write!(buf, "\x1b[{hd}m  Discovered repos\x1b[0m  \x1b[{dm}m{} found, {} selected\x1b[0m",
213	            candidates.len(), n_sel, hd = t.header, dm = t.text_dim).ok();
214	
215	        // Candidate rows
216	        let scroll = if sel + 1 > content_h { sel + 1 - content_h } else { 0 };
217	        for (row, i) in (scroll..candidates.len()).take(content_h).enumerate() {
218	            let screen_row = (row + 1) as u16;
219	            queue!(buf, cursor::MoveTo(0, screen_row), terminal::Clear(ClearType::UntilNewLine)).ok();
220	
221	            let c = &candidates[i];
222	            let check_col  = if selected[i] { t.fresh } else { t.text_faint };
223	            let check_char = if selected[i] { "x" } else { " " };
224	            let short = super::short_path(&c.directory);
225	            let remote_short: String = c.remote.chars().take(50).collect();
226	
227	            let line = format!(
228	                "  \x1b[{check_col}m[{check_char}]\x1b[0m  \x1b[{pm}m{:<20}\x1b[0m  \x1b[{dm}m{:<35}  {remote_short}\x1b[0m",
229	                c.name, short, pm = t.text_primary, dm = t.text_dim,
230	            );
231	
232	            if i == sel {
233	                let bg = t.sel_bg;
234	                let colored = super::with_bg(&line, bg);
235	                let vis = super::visible_width(&line);
236	                let pad = w.saturating_sub(vis);
237	                write!(buf, "\x1b[{bg}m{colored}{}\x1b[0m", " ".repeat(pad)).ok();
238	            } else {
239	                write!(buf, "{line}").ok();
240	            }
241	        }
242	
243	        // Clear empty rows
244	        for row in (candidates.len() + 1)..=content_h {
245	            queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine)).ok();
246	        }
247	
248	        super::draw_statusbar(
249	            &mut buf,
250	            "  ↑↓/jk navigate   space: toggle   a: toggle all   enter: register selected   esc: cancel  ",
251	            w, h,
252	        ).ok();
253	
254	        stdout.write_all(&buf).ok();
255	        stdout.flush().ok();
256	
257	        match event::read().ok()? {
258	            Event::Key(k) => match k.code {
259	                KeyCode::Esc => return None,
260	                KeyCode::Enter => {
261	                    let result = candidates.into_iter()
262	                        .zip(selected)
263	                        .filter_map(|(c, s)| if s { Some(c) } else { None })
264	                        .collect();
265	                    return Some(result);
266	                }
267	                KeyCode::Up   | KeyCode::Char('k') => { if sel > 0 { sel -= 1; } }
268	                KeyCode::Down | KeyCode::Char('j') => { if sel + 1 < candidates.len() { sel += 1; } }
269	                KeyCode::Char(' ') => { selected[sel] = !selected[sel]; }
270	                KeyCode::Char('a') => {
271	                    let all = selected.iter().all(|&s| s);
272	                    selected.iter_mut().for_each(|s| *s = !all);
273	                }
274	                _ => {}
275	            },
276	            Event::Resize(nw, nh) => {
277	                let (w2, h2) = (nw as usize, nh as usize);
278	                // reborrow will use updated w/h on next iteration — but they're
279	                // captured by value, so just continue (slight sizing glitch ok here)
280	                let _ = (w2, h2);
281	            }
282	            _ => {}
283	        }
284	    }
285	}
